function rationaleRespAcidosis_(ctx) {
  var lines = phPrefix_(ctx.pH);
  lines.push("PaCO\u2082 " + fmtLab_(ctx.pCO2) + " mmHg > 45: acidosis respiratoria primaria.");
  if (ctx.metaLow) {
    lines.push("HCO\u2083\u207B bajo coexisten; la hipercapnia y el pH \xE1cido predominan para nombrar el trastorno respiratorio.");
  }
  return lines.join(" ");
}
function rationaleRespAlkalosis_(ctx) {
  var lines = phPrefix_(ctx.pH);
  lines.push("PaCO\u2082 " + fmtLab_(ctx.pCO2) + " mmHg < 35: alcalosis respiratoria primaria.");
  if (ctx.metaLow) {
    lines.push("HCO\u2083\u207B bajo coexisten; la hipocapnia y el pH alcalino predominan frente al componente metab\xF3lico \xE1cido.");
  }
  return lines.join(" ");
}
function rationaleMixedAcidosis_(ctx) {
  var lines = phPrefix_(ctx.pH);
  lines.push(
    "En acidemia, HCO\u2083\u207B y PaCO\u2082 no encajan con un solo trastorno primario (ni acidosis metab\xF3lica clara con compensaci\xF3n, ni hipercapnia aislada)."
  );
  if (ctx.metaLow) lines.push("Hay acidosis metab\xF3lica (HCO\u2083\u207B bajo).");
  if (ctx.respHigh) lines.push("Hay retenci\xF3n de CO\u2082 (PaCO\u2082 elevada).");
  return lines.join(" ");
}
function rationaleMixedAlkalosis_(ctx) {
  var lines = phPrefix_(ctx.pH);
  lines.push("En alcalemia, HCO\u2083\u207B y PaCO\u2082 apuntan a procesos opuestos.");
  if (ctx.metaLow && ctx.respLow) {
    lines.push(
      "HCO\u2083\u207B bajo (tendencia metab\xF3lica \xE1cida) con PaCO\u2082 baja (alcalosis respiratoria); el pH alto indica que la hipocapnia pesa m\xE1s en el balance."
    );
  } else {
    if (ctx.metaLow) lines.push("HCO\u2083\u207B bajo sin alcalosis metab\xF3lica (HCO\u2083\u207B no elevado).");
    if (ctx.respLow) lines.push("PaCO\u2082 baja (hipocapnia).");
  }
  return lines.join(" ");
}
function rationaleCompensated_(ctx) {
  var lines = phPrefix_(ctx.pH);
  lines.push("Alteraciones de HCO\u2083\u207B y PaCO\u2082 se equilibran y dejan el pH casi normal.");
  if (ctx.metaLow && ctx.respLow) lines.push("Patr\xF3n acid\xF3tico compensado (HCO\u2083\u207B bajo + PaCO\u2082 baja).");
  if (ctx.metaHigh && ctx.respHigh) lines.push("Patr\xF3n alcal\xF3tico compensado (HCO\u2083\u207B alto + PaCO\u2082 alta).");
  return lines.join(" ");
}
function phPrefix_(pH) {
  if (pH == null) return [];
  if (pH < 7.35) return ["pH " + fmtLab_(pH, 2) + ": acidemia."];
  if (pH > 7.45) return ["pH " + fmtLab_(pH, 2) + ": alcalemia."];
  return ["pH " + fmtLab_(pH, 2) + ": en rango o compensado."];
}
function buildPrimaryRationale_(ctx) {
  if (ctx.pH == null && !ctx.mixedFromWinter) {
    return "Sin pH no se puede inferir el trastorno predominante con estas reglas.";
  }
  if (ctx.mixedFromWinter) return rationaleMixedWinter_(ctx);
  var primary = ctx.primary;
  var handlers = {
    "metabolic:acidosis": rationaleMetabolicAcidosis_,
    "metabolic:alkalosis": rationaleMetabolicAlkalosis_,
    "respiratory:acidosis": rationaleRespAcidosis_,
    "respiratory:alkalosis": rationaleRespAlkalosis_,
    "mixed:acidosis": rationaleMixedAcidosis_,
    "mixed:alkalosis": rationaleMixedAlkalosis_,
    "compensated:none": rationaleCompensated_,
    "compensated:acidosis": rationaleCompensated_,
    "compensated:alkalosis": rationaleCompensated_
  };
  var key = primary.disorder + ":" + primary.type;
  if (handlers[key]) return handlers[key](ctx);
  if (primary.disorder === "unknown") {
    return phPrefix_(ctx.pH).concat(["Datos insuficientes para clasificar con las reglas automatizadas."]).join(" ");
  }
  return phPrefix_(ctx.pH).join(" ");
}

// public/js/gaso-extended.mjs
function evaluateGasoExtended(input) {
  var inp = input || {};
  var pH = toFiniteNum_(inp.pH);
  var pCO2 = toFiniteNum_(inp.pCO2);
  var pO2 = toFiniteNum_(inp.pO2);
  var hco3 = toFiniteNum_(inp.hco3);
  var na = toFiniteNum_(inp.na);
  var cl = toFiniteNum_(inp.cl);
  var alb = toFiniteNum_(inp.alb);
  var naU = toFiniteNum_(inp.naU);
  var kU = toFiniteNum_(inp.kU);
  var clU = toFiniteNum_(inp.clU);
  var ageMonths = toFiniteNum_(inp.ageMonths);
  var fio2 = toFiniteNum_(inp.fio2);
  if (fio2 == null || !isFinite(fio2)) fio2 = 0.21;
  var agVal = computeAnionGapValue_(strLab_(na), strLab_(cl), strLab_(hco3)) ?? null;
  var agcVal = computeAlbuminCorrectedAnionGapValue_(strLab_(na), strLab_(cl), strLab_(hco3), strLab_(alb)) ?? null;
  var uagVal = toFiniteNum_(inp.uag);
  if (uagVal == null) {
    uagVal = computeUrinaryAnionGapValue_(strLab_(naU), strLab_(kU), strLab_(clU)) ?? null;
  }
  var phStep = buildPhStep_(pH);
  var metaLow = hco3 != null && hco3 < 22;
  var metaHigh = hco3 != null && hco3 > 26;
  var respLow = pCO2 != null && pCO2 < 35;
  var respHigh = pCO2 != null && pCO2 > 45;
  var winterCenter = hco3 != null ? 1.5 * hco3 + 8 : null;
  var mixedFromWinter = detectMixedFromWinter_(metaLow, pCO2, winterCenter, hco3);
  var classified = classifyPrimaryDisorder_(pH, metaLow, metaHigh, respLow, respHigh, mixedFromWinter);
  var primary = {
    disorder: classified.disorder,
    type: classified.type,
    rationale: buildPrimaryRationale_({
      pH,
      hco3,
      pCO2,
      primary: classified,
      mixedFromWinter,
      winterCenter,
      metaLow,
      metaHigh,
      respLow,
      respHigh
    })
  };
  var compensation = buildCompensation_(hco3, metaLow, pCO2, winterCenter);
  var anionGap = buildAnionGapStep_(agVal, agcVal);
  var urinaryAnionGap = buildUrinaryAnionGapStep_(uagVal);
  var deltaDelta = buildDeltaDeltaStep_(agVal, hco3, agcVal);
  var oxygenation = buildOxygenationStep_(pO2, pCO2, fio2, ageMonths);
  var summaryLines = buildSummaryLines_({
    phStep,
    primary,
    compensation,
    anionGap,
    urinaryAnionGap,
    deltaDelta,
    oxygenation
  });
  return {
    steps: {
      ph: phStep,
      primary,
      compensation,
      anionGap,
      urinaryAnionGap,
      deltaDelta,
      oxygenation
    },
    summaryLines
  };
}

// public/js/tend-group-gaso-slot.mjs
function serieNumFromLabSet(set, sec, fk) {
  var v = getSetTrendValueForSeries(set, sec, fk);
  return v != null && isFinite(v) ? v : null;
}
function fmtGasoNum(n, unit) {
  if (n == null || !isFinite(n)) return "\u2014";
  return String(n) + (unit ? " " + unit : "");
}
function primaryDisorderLabel(disorder, type) {
  var dMap = {
    metabolic: "Metab\xF3lico",
    respiratory: "Respiratorio",
    mixed: "Mixto",
    compensated: "Compensado",
    unknown: "Indeterminado"
  };
  var tMap = { acidosis: "acidosis", alkalosis: "alcalosis", none: "" };
  var d = dMap[String(disorder || "").toLowerCase()] || String(disorder || "\u2014");
  var t2 = tMap[String(type || "").toLowerCase()] || "";
  return t2 ? d + " \xB7 " + t2 : d;
}
function gasoMetricChip(label, value, tone) {
  var chip = document.createElement("span");
  chip.className = "tend-gaso-chip" + (tone ? " tend-gaso-chip--" + tone : "");
  var lbl = document.createElement("span");
  lbl.className = "tend-gaso-chip-label";
  lbl.textContent = label;
  var val = document.createElement("strong");
  val.className = "tend-gaso-chip-val";
  val.textContent = value;
  chip.appendChild(lbl);
  chip.appendChild(val);
  return chip;
}
function gasoSubMetric(label, value) {
  var sub = document.createElement("div");
  sub.className = "tend-gaso-sub";
  var lbl = document.createElement("span");
  lbl.className = "tend-gaso-sub-label";
  lbl.textContent = label;
  var val = document.createElement("span");
  val.className = "tend-gaso-sub-val";
  val.textContent = value;
  sub.appendChild(lbl);
  sub.appendChild(val);
  return sub;
}
function gasoStepCard(num4, title, bodyEl) {
  var art = document.createElement("article");
  art.className = "tend-gaso-step";
  var numEl = document.createElement("span");
  numEl.className = "tend-gaso-step-num";
  numEl.textContent = String(num4);
  var body = document.createElement("div");
  body.className = "tend-gaso-step-body";
  var h = document.createElement("h5");
  h.className = "tend-gaso-step-title";
  h.textContent = title;
  body.appendChild(h);
  body.appendChild(bodyEl);
  art.appendChild(numEl);
  art.appendChild(body);
  return art;
}
function gasoStepText(txt) {
  var p = document.createElement("p");
  p.className = "tend-gaso-step-text";
  p.textContent = String(txt || "");
  return p;
}
function phChipTone(pH) {
  if (pH == null) return "";
  if (pH < 7.35) return "low";
  if (pH > 7.45) return "high";
  return "";
}
function agChipTone(value) {
  return value != null && value > 12 ? "high" : "";
}
function extractGasoLabValues(latest) {
  return {
    na: serieNumFromLabSet(latest, "QS", "Na") ?? serieNumFromLabSet(latest, "ESC", "Na") ?? serieNumFromLabSet(latest, "GASES", "Na"),
    cl: serieNumFromLabSet(latest, "QS", "Cl") ?? serieNumFromLabSet(latest, "ESC", "Cl"),
    alb: serieNumFromLabSet(latest, "PFHs", "Alb"),
    pH: serieNumFromLabSet(latest, "GASES", "pH"),
    pCO2: serieNumFromLabSet(latest, "GASES", "pCO2"),
    pO2: serieNumFromLabSet(latest, "GASES", "pO2"),
    bic: serieNumFromLabSet(latest, "GASES", "Bica"),
    uag: serieNumFromLabSet(latest, "GASES", "UAG")
  };
}
function appendPrimaryStep(steps, ev) {
  var primaryBody = document.createElement("div");
  var primaryBadge = document.createElement("span");
  primaryBadge.className = "tend-gaso-badge tend-gaso-badge--tip";
  primaryBadge.tabIndex = 0;
  primaryBadge.textContent = primaryDisorderLabel(ev.steps.primary.disorder, ev.steps.primary.type);
  var primaryRationale = String(ev.steps.primary.rationale || "").trim();
  if (primaryRationale) {
    var primaryTipId = "tend-gaso-primary-rationale";
    primaryBadge.setAttribute("aria-describedby", primaryTipId);
    var primaryTip = document.createElement("span");
    primaryTip.id = primaryTipId;
    primaryTip.className = "tend-gaso-tip";
    primaryTip.setAttribute("role", "tooltip");
    primaryTip.textContent = primaryRationale;
    primaryBadge.appendChild(primaryTip);
  }
  primaryBody.appendChild(primaryBadge);
  steps.appendChild(gasoStepCard(2, "Trastorno predominante", primaryBody));
}
function appendCompensationStep(steps, cmp) {
  var cmpBody = document.createElement("div");
  var cmpGrid = document.createElement("div");
  cmpGrid.className = "tend-gaso-subgrid";
  if (cmp.expectedPCO2 != null) {
    cmpGrid.appendChild(gasoSubMetric("PaCO\u2082 Winter", "~" + cmp.expectedPCO2 + " mmHg"));
  }
  if (cmp.expectedHCO3Acute != null) {
    cmpGrid.appendChild(gasoSubMetric("HCO\u2083\u207B agudo", "~" + cmp.expectedHCO3Acute));
  }
  if (cmp.expectedHCO3Chronic != null) {
    cmpGrid.appendChild(gasoSubMetric("HCO\u2083\u207B cr\xF3nico", "~" + cmp.expectedHCO3Chronic));
  }
  if (cmpGrid.childNodes.length) cmpBody.appendChild(cmpGrid);
  cmpBody.appendChild(gasoStepText(cmp.note));
  steps.appendChild(gasoStepCard(3, "Compensaci\xF3n esperada", cmpBody));
}
function appendBadgeStep(steps, num4, title, badgeText, badgeWarn, interpretation) {
  var body = document.createElement("div");
  if (badgeText != null) {
    var badge = document.createElement("span");
    badge.className = "tend-gaso-badge" + (badgeWarn ? " tend-gaso-badge--warn" : "");
    badge.textContent = badgeText;
    body.appendChild(badge);
  }
  body.appendChild(gasoStepText(interpretation));
  steps.appendChild(gasoStepCard(num4, title, body));
}
function appendOxygenationStep(steps, ox) {
  var oxBody = document.createElement("div");
  var oxGrid = document.createElement("div");
  oxGrid.className = "tend-gaso-subgrid";
  if (ox.pfRatio != null) {
    oxGrid.appendChild(gasoSubMetric("P/F", "\u2248 " + ox.pfRatio));
  }
  if (ox.aaGradient != null) {
    oxGrid.appendChild(gasoSubMetric("Gradiente A\u2013a", "\u2248 " + ox.aaGradient + " mmHg"));
  }
  if (oxGrid.childNodes.length) oxBody.appendChild(oxGrid);
  oxBody.appendChild(gasoStepText(ox.note));
  steps.appendChild(gasoStepCard(7, "Oxigenaci\xF3n", oxBody));
}
function buildGasoMetricsRow(lab, ev) {
  var metrics = document.createElement("div");
  metrics.className = "tend-gaso-metrics";
  metrics.appendChild(gasoMetricChip("pH", fmtGasoNum(lab.pH), phChipTone(lab.pH)));
  metrics.appendChild(gasoMetricChip("PaCO\u2082", fmtGasoNum(lab.pCO2, "mmHg")));
  metrics.appendChild(gasoMetricChip("HCO\u2083\u207B", fmtGasoNum(lab.bic, "mEq/L")));
  var agDisplay = ev.steps.anionGap.corrected != null ? ev.steps.anionGap.corrected : ev.steps.anionGap.value;
  metrics.appendChild(
    gasoMetricChip(
      ev.steps.anionGap.corrected != null ? "AGc" : "Ani\xF3n gap",
      fmtGasoNum(agDisplay, "mEq/L"),
      agChipTone(agDisplay)
    )
  );
  if (ev.steps.urinaryAnionGap && ev.steps.urinaryAnionGap.value != null) {
    metrics.appendChild(
      gasoMetricChip("UAG", fmtGasoNum(ev.steps.urinaryAnionGap.value, "mEq/L"))
    );
  }
  return metrics;
}
function buildGasoSteps(ev) {
  var steps = document.createElement("div");
  steps.className = "tend-gaso-steps";
  steps.appendChild(gasoStepCard(1, "Estado \xE1cido-base", gasoStepText(ev.steps.ph.interpretation)));
  appendPrimaryStep(steps, ev);
  appendCompensationStep(steps, ev.steps.compensation);
  var ag = ev.steps.anionGap;
  var agBadge = ag.corrected != null ? "AGc " + ag.corrected + " (AG " + ag.value + ") mEq/L" : ag.value != null ? ag.value + " mEq/L" : null;
  var agHigh = (ag.corrected != null ? ag.corrected : ag.value) != null && (ag.corrected != null ? ag.corrected : ag.value) > 12;
  appendBadgeStep(steps, 4, "Ani\xF3n gap", agBadge, agHigh, ag.interpretation);
  var uag = ev.steps.urinaryAnionGap;
  appendBadgeStep(
    steps,
    5,
    "UAG (urinario)",
    uag && uag.value != null ? uag.value + " mEq/L" : null,
    false,
    uag ? uag.interpretation : ""
  );
  var dd = ev.steps.deltaDelta;
  appendBadgeStep(steps, 6, "Delta-delta", dd.value != null ? String(dd.value) : null, false, dd.interpretation);
  appendOxygenationStep(steps, ev.steps.oxygenation);
  return steps;
}
function appendGasoSummary(slot, summaryLines) {
  if (!summaryLines || !summaryLines.length) return;
  var hs = document.createElement("details");
  hs.className = "tend-gaso-summary";
  var sm = document.createElement("summary");
  sm.textContent = "Resumen r\xE1pido";
  hs.appendChild(sm);
  var ul = document.createElement("ul");
  ul.className = "tend-gaso-summary-list";
  summaryLines.forEach(function(ln) {
    var li = document.createElement("li");
    li.textContent = ln;
    ul.appendChild(li);
  });
  hs.appendChild(ul);
  slot.appendChild(hs);
}
function renderGasoEmptySlot(slot, escHtml2, message, isError) {
  var color = isError ? "var(--error)" : "var(--text-muted)";
  slot.innerHTML = '<p class="tend-empty" style="font-size:13px;color:' + color + ';">' + escHtml2(message) + "</p>";
}
function refillGasoExtendedSlot(slot, latest, fio2, escHtml2) {
  if (!slot) return;
  slot.innerHTML = "";
  if (!latest || !latest.parsedBySection) {
    renderGasoEmptySlot(slot, escHtml2, "Sin valores recientes disponibles para gasometr\xEDa.", false);
    return;
  }
  var lab = extractGasoLabValues(latest);
  try {
    var ev = evaluateGasoExtended({
      pH: lab.pH,
      pCO2: lab.pCO2,
      pO2: lab.pO2,
      hco3: lab.bic,
      na: lab.na,
      cl: lab.cl,
      alb: lab.alb,
      uag: lab.uag,
      fio2
    });
    var panel = document.createElement("div");
    panel.className = "tend-gaso-ext-panel";
    panel.appendChild(buildGasoMetricsRow(lab, ev));
    panel.appendChild(buildGasoSteps(ev));
    slot.appendChild(panel);
    appendGasoSummary(slot, ev.summaryLines);
  } catch (e) {
    renderGasoEmptySlot(slot, escHtml2, "No se pudo calcular la gasometr\xEDa extendida.", true);
    console.error("evaluateGasoExtended", e);
  }
}

// public/js/tend-group-gaso-dialog.mjs
function ensureGasoExtendedDialog(escHtml2, onBackdropClick) {
  var bd = document.getElementById("tend-gaso-ext-backdrop");
  if (bd) return bd;
  bd = document.createElement("div");
  bd.id = "tend-gaso-ext-backdrop";
  bd.className = "tend-gaso-ext-backdrop";
  bd.setAttribute("aria-hidden", "true");
  bd.style.display = "none";
  bd.innerHTML = '<div id="tend-gaso-ext-dialog" class="tend-gaso-ext-dialog" role="dialog" aria-modal="true" aria-labelledby="tend-gaso-ext-title"><div class="tend-gaso-ext-header"><div class="tend-gaso-ext-header-text"><h2 id="tend-gaso-ext-title">' + escHtml2("Gasometr\xEDa extendida") + '</h2><p class="tend-gaso-ext-subtitle">' + escHtml2("\xDAltimo estudio \xB7 interpretaci\xF3n \xE1cido-base") + '</p></div><div class="tend-gaso-ext-header-actions"><div class="tend-gaso-fio2-chip" role="group" aria-label="Fracci\xF3n inspirada de ox\xEDgeno"><span class="tend-gaso-fio2-chip-label">FiO\u2082</span><input type="number" class="tend-gaso-fio2-input" step="0.01" min="0.08" max="100" inputmode="decimal" aria-label="FiO\u2082 (0.21 o 21)" title="Fracci\xF3n 0.21 o porcentaje 21" /><span class="tend-gaso-fio2-chip-hint">0.21 \xB7 21%</span></div></div></div><div class="tend-gaso-extended-inner"></div></div>';
  bd.addEventListener("click", function(ev) {
    if (ev.target === bd) onBackdropClick();
  });
  document.body.appendChild(bd);
  return bd;
}
function closeGasoExtendedBackdrop() {
  var bd = document.getElementById("tend-gaso-ext-backdrop");
  if (!bd) return;
  document.body.classList.remove("tend-gaso-ext-open");
  closeOverlayAnimated(bd, function() {
    bd.style.display = "none";
  });
}
function showGasoExtendedBackdrop(bd) {
  cancelOverlayClose(bd);
  bd.style.display = "flex";
  bd.setAttribute("aria-hidden", "false");
  document.body.classList.add("tend-gaso-ext-open");
}
function parseFio2Input(raw, fallback) {
  var n = parseFloat(String(raw == null ? "" : raw).replace(",", "."));
  if (!isFinite(n)) return fallback;
  if (n > 3) return Math.min(Math.max(n / 100, 0.08), 1);
  return Math.min(Math.max(n, 0.08), 1);
}
function formatFio2Display(fio2) {
  var asPercent = Math.abs(fio2 * 100 - Math.round(fio2 * 100)) < 1e-6 && fio2 <= 1;
  return asPercent ? String(fio2.toFixed(2)) : String(fio2);
}
function wireGasoExtendedDialog(bd, state2, onRerun) {
  var inp = bd.querySelector(".tend-gaso-fio2-input");
  if (!inp || inp._gasoWired) return;
  inp._gasoWired = true;
  inp.value = formatFio2Display(state2.gasoExtendedFio2);
  inp.addEventListener("change", onRerun);
  inp.addEventListener("input", onRerun);
}

// public/js/tend-group-gaso.mjs
function isAbgAnalysisHidden2() {
  return true;
}
function defaultEsc(t2) {
  return String(t2 == null ? "" : t2);
}
function createTendGroupGasoApi(deps, state2) {
  function escHtml2(t2) {
    return (deps.esc || defaultEsc)(t2);
  }
  function closeGasoExtended() {
    closeGasoExtendedBackdrop();
  }
  function rerunGasoSlot(bd) {
    var inp = bd.querySelector(".tend-gaso-fio2-input");
    state2.gasoExtendedFio2 = parseFio2Input(inp && inp.value, state2.gasoExtendedFio2);
    refillGasoExtendedSlot(
      bd.querySelector(".tend-gaso-extended-inner"),
      state2.historyDesc[0],
      state2.gasoExtendedFio2,
      escHtml2
    );
  }
  function openGasoExtended() {
    if (isAbgAnalysisHidden2()) {
      if (deps.showToast) deps.showToast("El an\xE1lisis de gasometr\xEDa no est\xE1 disponible en R+.", "info");
      return;
    }
    var patientId = deps.getActiveId();
    if (!patientId) return;
    var historyDesc = sortLabHistoryChronological(deps.getHistory() || []);
    if (!historyDesc.length) {
      if (deps.showToast) deps.showToast("Sin laboratorio reciente para gasometr\xEDa.", "warn");
      return;
    }
    state2.patientId = patientId;
    state2.historyDesc = historyDesc;
    var latest = historyDesc[0];
    var hasGaso = latest && latest.parsedBySection && latest.parsedBySection.GASES && serieNumFromLabSet(latest, "GASES", "pH") != null;
    if (!hasGaso) {
      if (deps.showToast) deps.showToast("No hay gasometr\xEDa en el \xFAltimo estudio.", "warn");
      return;
    }
    var bd = ensureGasoExtendedDialog(escHtml2, closeGasoExtended);
    wireGasoExtendedDialog(bd, state2, function() {
      rerunGasoSlot(bd);
    });
    refillGasoExtendedSlot(
      bd.querySelector(".tend-gaso-extended-inner"),
      latest,
      state2.gasoExtendedFio2,
      escHtml2
    );
    showGasoExtendedBackdrop(bd);
  }
  return { openGasoExtended, closeGasoExtended };
}

