// public/js/features/historia-clinica-app-panel/render-medicamentos.mjs
function medicamentoRowHtml(m, i) {
  const linked = m.linkedFrom === ERC_CONDITION_ID;
  const ro = linked ? ' readonly tabindex="-1" title="Editar en la tarjeta de enfermedad renal cr\xF3nica"' : "";
  const tag = linked ? ' <span class="hc-tag">ERC</span>' : "";
  return '<div class="hc-entry-row' + (linked ? " hc-entry-row--linked" : "") + '" data-medicamento-idx="' + i + '"><div class="field-group"><label>Medicamento' + tag + '</label><input type="text" data-med-field="medication" value="' + esc(m.medication || "") + '" placeholder="Nombre gen\xE9rico o comercial"' + ro + '></div><div class="field-group"><label>V\xEDa de administraci\xF3n</label><input type="text" data-med-field="route" value="' + esc(m.route || "") + '" placeholder="VO, IV, SC, inhalada\u2026"' + ro + '></div><div class="field-group"><label>Dosis</label><input type="text" data-med-field="dosage" value="' + esc(m.dosage || "") + '" placeholder="ej. 850 mg"' + ro + '></div><div class="field-group"><label>Frecuencia</label><input type="text" data-med-field="frequency" value="' + esc(m.frequency || "") + '" placeholder="ej. c/12 h"' + ro + '></div><button type="button" class="btn-remove" data-medicamento-remove="' + i + '" aria-label="Quitar">\xD7</button></div>';
}
function createRenderMedicamentos(ctx, renderers) {
  const { container, app, emit, getErcDetail } = ctx;
  return function renderMedicamentos() {
    const host = container.querySelector("#hc-app-medicamentos");
    if (!host) return;
    const list = app.medicamentosActuales || [];
    if (!list.length) {
      host.innerHTML = emptyHint("Medicamento, v\xEDa, dosis y frecuencia de cada f\xE1rmaco activo.");
      return;
    }
    host.innerHTML = list.map(medicamentoRowHtml).join("");
    host.querySelectorAll("[data-med-field]").forEach(function(el) {
      el.addEventListener("input", function() {
        const row = el.closest("[data-medicamento-idx]");
        const idx = Number(row.getAttribute("data-medicamento-idx"));
        const m = app.medicamentosActuales[idx];
        if (!m || m.linkedFrom === ERC_CONDITION_ID) return;
        m[el.getAttribute("data-med-field")] = el.value;
        emit();
      });
    });
    host.querySelectorAll("[data-medicamento-remove]").forEach(function(btn) {
      btn.onclick = function() {
        const idx = Number(btn.getAttribute("data-medicamento-remove"));
        const m = app.medicamentosActuales[idx];
        if (m && m.linkedFrom === ERC_CONDITION_ID) {
          const erc = getErcDetail();
          erc.medications = erc.medications.filter(function(x) {
            return x.id !== m.id;
          });
          syncErcMedicationsToApp(app);
          renderers.renderErcMeds();
        } else {
          app.medicamentosActuales.splice(idx, 1);
        }
        renderers.renderMedicamentos();
        emit();
      };
    });
  };
}

// public/js/features/historia-clinica-app-panel/entry-list-wire.mjs
function wireEntryList(host, list, rowAttr, fieldAttr, onDateChange, emit, rerender) {
  host.querySelectorAll(".hc-flex-date").forEach(wireFlexibleDate);
  host.querySelectorAll("[data-" + fieldAttr + "]").forEach(function(el) {
    el.addEventListener("input", function() {
      const row = el.closest("[data-" + rowAttr + "-idx]");
      const idx = Number(row.getAttribute("data-" + rowAttr + "-idx"));
      const key = el.getAttribute("data-" + fieldAttr);
      if (!list[idx]) return;
      list[idx][key] = el.value;
      emit();
    });
  });
  host.querySelectorAll("[data-" + rowAttr + "-remove]").forEach(function(btn) {
    btn.onclick = function() {
      list.splice(Number(btn.getAttribute("data-" + rowAttr + "-remove")), 1);
      rerender();
      emit();
    };
  });
  host.querySelectorAll(".hc-flex-date").forEach(function(wrap) {
    wrap.querySelectorAll("input,select").forEach(function(el) {
      el.addEventListener("change", function() {
        const row = wrap.closest("[data-" + rowAttr + "-idx]");
        const idx = Number(row.getAttribute("data-" + rowAttr + "-idx"));
        onDateChange(idx, wrap);
        emit();
      });
    });
  });
}

