// public/js/features/historia-clinica-app-panel/render-lists.mjs
function createListRenderers(ctx) {
  const renderers = {};
  renderers.renderMedicamentos = createRenderMedicamentos(ctx, renderers);
  renderers.renderErcMeds = createRenderErcMeds(ctx, renderers);
  renderers.renderAlergias = createRenderAlergias(ctx);
  renderers.renderTrauma = createRenderTrauma(ctx);
  renderers.renderTransfusiones = createRenderTransfusiones(ctx);
  renderers.renderCirugias = createRenderCirugias(ctx);
  renderers.renderHosps = createRenderHosps(ctx);
  return renderers;
}

// public/js/features/historia-clinica-app-panel/wire-actions.mjs
function wireAlergiaToggle(ctx, renderers) {
  const { container, app, emit } = ctx;
  const negadoEl = container.querySelector("#hc-app-alergias-negado");
  const alBody = container.querySelector("#hc-app-alergias-body");
  const alActions = container.querySelector("#hc-app-alergias-actions");
  if (!negadoEl) return { negadoEl, alBody, alActions };
  negadoEl.addEventListener("change", function() {
    app.alergiasNegado = negadoEl.checked;
    if (app.alergiasNegado) app.alergiaMedicamentos = [];
    alBody.classList.toggle("hc-app-special-body--hidden", app.alergiasNegado);
    alActions.classList.toggle("hc-app-special-body--hidden", app.alergiasNegado);
    if (!app.alergiasNegado) renderers.renderAlergias();
    emit();
  });
  return { negadoEl, alBody, alActions };
}
function wireAppFields(ctx) {
  const { container, app, emit } = ctx;
  container.querySelectorAll("[data-app-field]").forEach(function(el) {
    el.addEventListener("input", function() {
      app[el.getAttribute("data-app-field")] = el.value;
      emit();
    });
  });
}
function wireAddButtons(ctx, renderers, alergiaUi) {
  const { container, app, emit } = ctx;
  const { negadoEl, alBody, alActions } = alergiaUi;
  const addAlergia = container.querySelector("#hc-app-add-alergia");
  if (addAlergia) {
    addAlergia.onclick = function() {
      app.alergiasNegado = false;
      if (negadoEl) negadoEl.checked = false;
      app.alergiaMedicamentos.push({ id: newRowId("al"), medication: "" });
      alBody.classList.remove("hc-app-special-body--hidden");
      alActions.classList.remove("hc-app-special-body--hidden");
      renderers.renderAlergias();
      emit();
    };
  }
  const addTrauma = container.querySelector("#hc-app-add-trauma");
  if (addTrauma) {
    addTrauma.onclick = function() {
      app.traumaticosEntries.push({
        id: newRowId("tr"),
        description: "",
        date: defaultFlexibleDate()
      });
      renderers.renderTrauma();
      emit();
    };
  }
  const addTf = container.querySelector("#hc-app-add-transfusion");
  if (addTf) {
    addTf.onclick = function() {
      app.transfusionesEntries.push({
        id: newRowId("tf"),
        units: "",
        adverseReactions: "",
        date: defaultFlexibleDate()
      });
      renderers.renderTransfusiones();
      emit();
    };
  }
  const addMed = container.querySelector("#hc-app-add-medicamento");
  if (addMed) {
    addMed.onclick = function() {
      app.medicamentosActuales.push({
        id: newRowId("med"),
        medication: "",
        route: "",
        dosage: "",
        frequency: ""
      });
      renderers.renderMedicamentos();
      emit();
    };
  }
  const addCir = container.querySelector("#hc-app-add-cirugia");
  if (addCir) {
    addCir.onclick = function() {
      app.cirugias.push({ procedure: "", complications: "", date: defaultFlexibleDate() });
      renderers.renderCirugias();
      emit();
    };
  }
  const addHosp = container.querySelector("#hc-app-add-hosp");
  if (addHosp) {
    addHosp.onclick = function() {
      app.hospitalizaciones.push({
        reason: "",
        duration: "",
        complications: "",
        date: defaultFlexibleDate()
      });
      renderers.renderHosps();
      emit();
    };
  }
}
function wirePanelActions(ctx, renderers) {
  const { container } = ctx;
  container.querySelectorAll(".hc-flex-date").forEach(wireFlexibleDate);
  const alergiaUi = wireAlergiaToggle(ctx, renderers);
  wireAppFields(ctx);
  wireAddButtons(ctx, renderers, alergiaUi);
}

// public/js/features/historia-clinica-app-panel/wire.mjs
function wireErcCard(ctx, renderers) {
  const { container, app, emit, getErcDetail } = ctx;
  const card = container.querySelector('[data-cond-id="' + ERC_CONDITION_ID + '"]');
  if (!card) return;
  const erc = getErcDetail();
  card.querySelectorAll("[data-erc-field]").forEach(function(el) {
    el.addEventListener("input", function() {
      erc[el.getAttribute("data-erc-field")] = el.value;
      emit();
    });
    el.addEventListener("change", function() {
      erc[el.getAttribute("data-erc-field")] = el.value;
      emit();
    });
  });
  const flex = card.querySelector(".hc-flex-date");
  if (flex) {
    flex.querySelectorAll("input,select").forEach(function(el) {
      el.addEventListener("change", function() {
        erc.diagnosedAt = readFlexibleDate(flex);
        emit();
      });
    });
  }
  const addMed = card.querySelector("#hc-erc-add-med");
  if (addMed) {
    addMed.onclick = function() {
      erc.medications.push({
        id: newRowId("erc"),
        medication: "",
        route: "",
        dosage: "",
        frequency: ""
      });
      syncErcMedicationsToApp(app);
      renderers.renderErcMeds();
      renderers.renderMedicamentos();
      emit();
    };
  }
  renderers.renderErcMeds();
}
function wireConditionCards(ctx) {
  const { container, app, emit, remount } = ctx;
  container.querySelectorAll(".hc-check-chip-input").forEach(function(el) {
    el.addEventListener("change", function() {
      const id = el.getAttribute("data-app-cond");
      const set = new Set(app.conditions || []);
      if (el.checked) {
        set.add(id);
        if (id === ERC_CONDITION_ID) {
          app.conditionDetails = app.conditionDetails || {};
          app.conditionDetails[ERC_CONDITION_ID] = normalizeErcDetail(
            app.conditionDetails[ERC_CONDITION_ID]
          );
        }
      } else {
        set.delete(id);
        if (id === ERC_CONDITION_ID) purgeErcMedicationsFromApp(app);
        else if (app.conditionDetails && app.conditionDetails[id]) delete app.conditionDetails[id];
      }
      app.conditions = Array.from(set);
      remount();
      emit();
    });
  });
  const addCustom = container.querySelector("#hc-app-add-custom");
  if (addCustom) {
    addCustom.onclick = function() {
      const input = container.querySelector("#hc-app-custom-label");
      const label = input && input.value ? input.value.trim() : "";
      if (!label) return;
      const id = newRowId("custom");
      app.customConditions.push({ id, label });
      app.conditions.push(id);
      app.conditionDetails[id] = { treatment: "" };
      if (input) input.value = "";
      remount();
      emit();
    };
  }
  container.querySelectorAll(".hc-app-cond-card:not(.hc-app-cond-card--erc)").forEach(function(card) {
    const id = card.getAttribute("data-cond-id");
    card.querySelectorAll("[data-cond-field]").forEach(function(el) {
      el.addEventListener("input", function() {
        app.conditionDetails[id] = app.conditionDetails[id] || {};
        app.conditionDetails[id][el.getAttribute("data-cond-field")] = el.value;
        emit();
      });
    });
    const flex = card.querySelector(".hc-flex-date");
    if (flex) {
      flex.querySelectorAll("input,select").forEach(function(el) {
        el.addEventListener("change", function() {
          app.conditionDetails[id] = app.conditionDetails[id] || {};
          app.conditionDetails[id].diagnosedAt = readFlexibleDate(flex);
          emit();
        });
      });
    }
  });
}

// public/js/features/historia-clinica-app-panel/mount.mjs
function mountHistoriaAppPanel(container, app, catalog, onChange) {
  if (!container) return;
  app = ensureApp(app);
  catalog = catalog || {};
  const options = catalogOptions2(catalog);
  container.innerHTML = buildPanelShellHtml(app, catalog, options);
  function emit() {
    syncErcMedicationsToApp(app);
    onChange(ensureApp(app));
  }
  function getErcDetail() {
    app.conditionDetails = app.conditionDetails || {};
    app.conditionDetails[ERC_CONDITION_ID] = normalizeErcDetail(
      app.conditionDetails[ERC_CONDITION_ID]
    );
    return app.conditionDetails[ERC_CONDITION_ID];
  }
  const ctx = {
    container,
    app,
    catalog,
    onChange,
    emit,
    getErcDetail,
    remount: function remount() {
      mountHistoriaAppPanel(container, app, catalog, onChange);
    }
  };
  const renderers = createListRenderers(ctx);
  renderers.renderAlergias();
  renderers.renderTrauma();
  renderers.renderTransfusiones();
  renderers.renderMedicamentos();
  renderers.renderCirugias();
  renderers.renderHosps();
  wireErcCard(ctx, renderers);
  wireConditionCards(ctx);
  wirePanelActions(ctx, renderers);
}

// public/js/features/historia-clinica-ahf-panel-render.mjs
function catalogOptions3(map) {
  return Object.keys(map || {}).map(function(id) {
    return { id, label: map[id] };
  });
}
function defaultAhf() {
  return {
    conditions: [],
    customConditions: [],
    entries: [],
    descripcionDetallada: ""
  };
}
function ensureAhf(ahf) {
  return syncAhfConditionsFromEntries(Object.assign(defaultAhf(), ahf || {}));
}
function newEntryId() {
  return "ahf_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 7);
}
function conditionLabel2(id, catalog, customConditions) {
  if (catalog && catalog[id]) return catalog[id];
  const c = (customConditions || []).find(function(row) {
    return row && row.id === id;
  });
  return c && c.label || id;
}
function entriesForCondition(ahf, conditionId) {
  return (ahf.entries || []).filter(function(e) {
    return e && e.conditionId === conditionId;
  });
}
function blankAhfEntry(conditionId) {
  return {
    id: newEntryId(),
    conditionId,
    relativeId: "",
    diagnosis: "",
    treatment: "",
    vitalStatus: "desconocido"
  };
}
function relativeSelectHtml(entryId, value) {
  let html = '<select class="hc-ahf-relative" data-entry-id="' + esc(entryId) + '">';
  html += '<option value="">\u2014 Familiar \u2014</option>';
  AHF_RELATIVES.forEach(function(rel) {
    html += '<option value="' + esc(rel.id) + '"' + (value === rel.id ? " selected" : "") + ">" + esc(rel.label) + "</option>";
  });
  return html + "</select>";
}
function entryRowHtml(entry) {
  const e = entry || {};
  const id = e.id || newEntryId();
  const vital = e.vitalStatus || "desconocido";
  const deadFields = vital === "fallecido";
  return '<div class="hc-ahf-entry" data-entry-id="' + esc(id) + '"><div class="field-group"><label>Familiar</label>' + relativeSelectHtml(id, e.relativeId) + '</div><div class="field-group"><label>Diagn\xF3stico</label><input type="text" data-ahf-field="diagnosis" value="' + esc(e.diagnosis || "") + '"></div><div class="field-group"><label>Tratamiento</label><input type="text" data-ahf-field="treatment" value="' + esc(e.treatment || "") + '"></div><div class="field-group"><label>Estado</label><select data-ahf-field="vitalStatus"><option value="vivo"' + (vital === "vivo" ? " selected" : "") + '>Vivo/a</option><option value="fallecido"' + (vital === "fallecido" ? " selected" : "") + '>Fallecido/a</option><option value="desconocido"' + (vital === "desconocido" ? " selected" : "") + '>No especificado</option></select></div><div class="hc-ahf-death-fields' + (deadFields ? "" : " hc-ahf-death-fields--hidden") + '"><div class="field-group"><label>Edad al fallecer</label><input type="number" min="0" max="120" data-ahf-field="ageAtDeath" value="' + esc(e.ageAtDeath != null ? e.ageAtDeath : "") + '"></div><div class="field-group"><label>Causa de muerte</label><input type="text" data-ahf-field="causeOfDeath" value="' + esc(e.causeOfDeath || "") + '"></div></div><button type="button" class="btn-remove" data-ahf-remove aria-label="Quitar familiar">\xD7</button></div>';
}
function buildAhfPanelHtml(ahf, catalog) {
  const options = catalogOptions3(catalog);
  const activeIds = new Set(ahf.conditions || []);
  let html = '<div class="hc-ahf-panel">';
  html += '<div class="hc-checklist-options hc-checklist-options--grid">';
  options.forEach(function(opt) {
    const checked = activeIds.has(opt.id) ? " checked" : "";
    html += '<label class="hc-check-chip"><input type="checkbox" class="hc-check-chip-input" data-ahf-cond="' + esc(opt.id) + '"' + checked + '><span class="hc-check-chip-label">' + esc(opt.label) + "</span></label>";
  });
  html += "</div>";
  html += '<div class="hc-app-custom-row"><div class="field-group" style="flex:1"><label>Otra enfermedad familiar</label><input type="text" id="hc-ahf-custom-label" placeholder="Nombre de la enfermedad"></div><button type="button" class="btn-med-secondary" id="hc-ahf-add-custom">Agregar</button></div>';
  const positiveIds = (ahf.conditions || []).slice();
  if (positiveIds.length) {
    html += '<div class="hc-ahf-conditions-detail">';
    positiveIds.forEach(function(cid) {
      const entries = entriesForCondition(ahf, cid);
      html += '<details class="card hc-ahf-cond-card" open data-cond-id="' + esc(cid) + '"><summary class="card-header">' + esc(conditionLabel2(cid, catalog, ahf.customConditions)) + '</summary><div class="card-body hc-ahf-entries" data-cond-id="' + esc(cid) + '">';
      if (entries.length) {
        entries.forEach(function(entry) {
          html += entryRowHtml(entry);
        });
      } else {
        html += '<p class="profile-hint">Agrega al menos un familiar para esta enfermedad.</p>';
      }
      html += '</div><button type="button" class="btn-add-row" data-ahf-add-relative="' + esc(cid) + '">+ Agregar familiar</button></details>';
    });
    html += "</div>";
  }
  html += '<div class="field-group"><label>Notas adicionales</label><textarea rows="3" data-ahf-field="descripcionDetallada">' + esc(ahf.descripcionDetallada) + "</textarea></div></div>";
  return html;
}

// public/js/features/historia-clinica-ahf-panel-wire.mjs
function findEntry(ahf, id) {
  return (ahf.entries || []).find(function(e) {
    return e && e.id === id;
  });
}
function applyEntryFieldChange(entry, row, el) {
  const field = el.getAttribute("data-ahf-field");
  if (field === "ageAtDeath") {
    const n = Number(el.value);
    entry.ageAtDeath = Number.isFinite(n) ? n : null;
    return;
  }
  if (field === "vitalStatus") {
    entry.vitalStatus = el.value;
    const deathWrap = row.querySelector(".hc-ahf-death-fields");
    if (deathWrap) {
      deathWrap.classList.toggle("hc-ahf-death-fields--hidden", el.value !== "fallecido");
    }
    if (el.value !== "fallecido") {
      entry.ageAtDeath = null;
      entry.causeOfDeath = "";
    }
    return;
  }
  entry[field] = el.value;
}
function wireConditionCheckboxes(container, ahf, catalog, onChange, remount) {
  container.querySelectorAll(".hc-check-chip-input[data-ahf-cond]").forEach(function(el) {
    el.addEventListener("change", function() {
      const cid = el.getAttribute("data-ahf-cond");
      if (el.checked) {
        if ((ahf.conditions || []).indexOf(cid) < 0) {
          ahf.conditions = (ahf.conditions || []).concat([cid]);
        }
        if (!entriesForCondition(ahf, cid).length) {
          ahf.entries = ahf.entries || [];
          ahf.entries.push(blankAhfEntry(cid));
        }
      } else {
        ahf.conditions = (ahf.conditions || []).filter(function(id) {
          return id !== cid;
        });
        ahf.entries = (ahf.entries || []).filter(function(e) {
          return e.conditionId !== cid;
        });
      }
      remount();
      onChange(ensureAhf(ahf));
    });
  });
}
function wireCustomConditionAdd(container, ahf, catalog, onChange, remount) {
  const addCustom = container.querySelector("#hc-ahf-add-custom");
  if (!addCustom) return;
  addCustom.onclick = function() {
    const input = container.querySelector("#hc-ahf-custom-label");
    const label = input && input.value ? input.value.trim() : "";
    if (!label) return;
    const id = "custom_" + Date.now().toString(36);
    ahf.customConditions = ahf.customConditions || [];
    ahf.customConditions.push({ id, label });
    ahf.conditions = (ahf.conditions || []).concat([id]);
    ahf.entries = ahf.entries || [];
    ahf.entries.push(blankAhfEntry(id));
    if (input) input.value = "";
    remount();
    onChange(ensureAhf(ahf));
  };
}
function wireAddRelativeButtons(container, ahf, onChange, remount) {
  container.querySelectorAll("[data-ahf-add-relative]").forEach(function(btn) {
    btn.onclick = function() {
      const cid = btn.getAttribute("data-ahf-add-relative");
      ahf.entries = ahf.entries || [];
      ahf.entries.push(blankAhfEntry(cid));
      remount();
      onChange(ensureAhf(ahf));
    };
  });
}
function wireEntryRow(container, row, ahf, onChange, remount) {
  const entryId = row.getAttribute("data-entry-id");
  const entry = findEntry(ahf, entryId);
  if (!entry) return;
  row.querySelectorAll("[data-ahf-field]").forEach(function(el) {
    function apply() {
      applyEntryFieldChange(entry, row, el);
      onChange(ensureAhf(ahf));
    }
    el.addEventListener("input", apply);
    el.addEventListener("change", apply);
  });
  const relSel = row.querySelector(".hc-ahf-relative");
  if (relSel) {
    relSel.addEventListener("change", function() {
      entry.relativeId = relSel.value;
      onChange(ensureAhf(ahf));
    });
  }
  const removeBtn = row.querySelector("[data-ahf-remove]");
  if (removeBtn) {
    removeBtn.onclick = function() {
      ahf.entries = (ahf.entries || []).filter(function(e) {
        return e.id !== entryId;
      });
      if (!entriesForCondition(ahf, entry.conditionId).length) {
        ahf.conditions = (ahf.conditions || []).filter(function(id) {
          return id !== entry.conditionId;
        });
      }
      remount();
      onChange(ensureAhf(ahf));
    };
  }
}
function wireNotesField(container, ahf, onChange) {
  const notes2 = container.querySelector('[data-ahf-field="descripcionDetallada"]');
  if (!notes2) return;
  notes2.addEventListener("input", function() {
    ahf.descripcionDetallada = notes2.value;
    onChange(ensureAhf(ahf));
  });
}
function wireAhfPanelInteractions(container, ahf, catalog, onChange, remount) {
  wireConditionCheckboxes(container, ahf, catalog, onChange, remount);
  wireCustomConditionAdd(container, ahf, catalog, onChange, remount);
  wireAddRelativeButtons(container, ahf, onChange, remount);
  container.querySelectorAll(".hc-ahf-entry").forEach(function(row) {
    wireEntryRow(container, row, ahf, onChange, remount);
  });
  wireNotesField(container, ahf, onChange);
}

// public/js/features/historia-clinica-ahf-panel.mjs
function mountHistoriaAhfPanel(container, ahf, catalog, onChange) {
  if (!container) return;
  ahf = ensureAhf(ahf);
  catalog = catalog || {};
  function remount() {
    mountHistoriaAhfPanel(container, ahf, catalog, onChange);
  }
  container.innerHTML = buildAhfPanelHtml(ahf, catalog);
  wireAhfPanelInteractions(container, ahf, catalog, onChange, remount);
}

// public/js/features/historia-clinica-medicamento-rows.mjs
function emptyHint2(text) {
  return '<p class="hc-empty-hint">' + esc(text) + "</p>";
}
function renderMedicamentoRowHtml(m, i, isReadOnly, canRemove) {
  const linked = isReadOnly(m);
  const ro = linked ? ' readonly tabindex="-1" title="No editable en este bloque"' : "";
  const tag = linked ? ' <span class="hc-tag">Vinculado</span>' : "";
  return '<div class="hc-entry-row' + (linked ? " hc-entry-row--linked" : "") + '" data-medicamento-idx="' + i + '"><div class="field-group"><label>Medicamento' + tag + '</label><input type="text" data-med-field="medication" value="' + esc(m.medication || "") + '" placeholder="Nombre gen\xE9rico o comercial"' + ro + '></div><div class="field-group"><label>V\xEDa de administraci\xF3n</label><input type="text" data-med-field="route" value="' + esc(m.route || "") + '" placeholder="VO, IV, SC, inhalada\u2026"' + ro + '></div><div class="field-group"><label>Dosis</label><input type="text" data-med-field="dosage" value="' + esc(m.dosage || "") + '" placeholder="ej. 850 mg"' + ro + '></div><div class="field-group"><label>Frecuencia</label><input type="text" data-med-field="frequency" value="' + esc(m.frequency || "") + '" placeholder="ej. c/12 h"' + ro + "></div>" + (canRemove && !linked ? '<button type="button" class="btn-remove" data-medicamento-remove="' + i + '" aria-label="Quitar">\xD7</button>' : "") + "</div>";
}
function buildMedicamentoRowsHtml(list, opts) {
  const emptyText = opts.emptyHint || "Medicamento, v\xEDa, dosis y frecuencia de cada f\xE1rmaco activo.";
  const canRemove = opts.allowRemove !== false;
  const isReadOnly = typeof opts.readOnlyFilter === "function" ? opts.readOnlyFilter : function() {
    return false;
  };
  let html = '<div class="hc-medicamentos-list">';
  if (!list.length) {
    html += emptyHint2(emptyText);
  } else {
    html += list.map((m, i) => renderMedicamentoRowHtml(m, i, isReadOnly, canRemove)).join("");
  }
  html += "</div>";
  html += '<button type="button" class="btn-add-row hc-medicamentos-add">' + esc(opts.addLabel || "+ Agregar medicamento") + "</button>";
  return { html, isReadOnly, canRemove };
}
function wireMedicamentoRowEvents(host, list, opts) {
  const isReadOnly = typeof opts.readOnlyFilter === "function" ? opts.readOnlyFilter : function() {
    return false;
  };
  function emit() {
    const next = [];
    host.querySelectorAll("[data-medicamento-idx]").forEach(function(row) {
      const idx = Number(row.getAttribute("data-medicamento-idx"));
      const base = list[idx] || {};
      if (isReadOnly(base)) {
        next.push(base);
        return;
      }
      const m = { id: base.id || newMedicamentoRowId("med") };
      row.querySelectorAll("[data-med-field]").forEach(function(el) {
        m[el.getAttribute("data-med-field")] = el.value;
      });
      next.push(m);
    });
    opts.onChange(normalizeMedicamentosList(next));
  }
  function rerender() {
    mountMedicamentoRows(host, Object.assign({}, opts, { list }));
  }
  host.querySelectorAll("[data-med-field]").forEach(function(el) {
    el.addEventListener("input", function() {
      const row = el.closest("[data-medicamento-idx]");
      const idx = Number(row.getAttribute("data-medicamento-idx"));
      if (isReadOnly(list[idx])) return;
      emit();
    });
  });
  host.querySelectorAll("[data-medicamento-remove]").forEach(function(btn) {
    btn.onclick = function() {
      list.splice(Number(btn.getAttribute("data-medicamento-remove")), 1);
      rerender();
      emit();
    };
  });
  const addBtn = host.querySelector(".hc-medicamentos-add");
  if (addBtn) {
    addBtn.onclick = function() {
      list.push({
        id: newMedicamentoRowId("med"),
        medication: "",
        route: "",
        dosage: "",
        frequency: ""
      });
      rerender();
      emit();
      const rows = host.querySelectorAll("[data-medicamento-idx]");
      const last = rows[rows.length - 1];
      const med = last && last.querySelector('[data-med-field="medication"]');
      if (med) med.focus();
    };
  }
}
function mountMedicamentoRows(host, opts) {
  if (!host) return;
  opts = opts || {};
  const list = normalizeMedicamentosList(opts.list);
  const built = buildMedicamentoRowsHtml(list, opts);
  host.innerHTML = built.html;
  wireMedicamentoRowEvents(host, list, opts);
}

// public/js/features/historia-clinica-genero-panel.mjs
function ageBodyHtml(spec, val) {
  val = val && typeof val === "object" ? val : {};
  return '<input type="number" min="0" max="99" step="1" data-genero-part="edad" data-genero-id="' + esc(spec.id) + '" value="' + esc(val.edad || "") + '" placeholder="Edad en a\xF1os">';
}
function fumBodyHtml(spec, val) {
  val = val && typeof val === "object" ? val : {};
  return '<div class="hc-genero-inline"><div class="field-group hc-genero-inline-field"><label>FUM</label><input type="text" data-genero-part="fum" data-genero-id="' + esc(spec.id) + '" value="' + esc(val.fum || "") + '" placeholder="DD/MM/AA"></div><div class="field-group hc-genero-inline-field"><label>Ciclo</label><input type="text" data-genero-part="ciclo" data-genero-id="' + esc(spec.id) + '" value="' + esc(val.ciclo || "") + '" placeholder="Regular, 28 d\xEDas\u2026"></div></div>';
}
function gpacBodyHtml(spec, val) {
  val = val && typeof val === "object" ? val : {};
  const cells = [
    ["g", "Gestas (G)"],
    ["p", "Partos (P)"],
    ["a", "Abortos (A)"],
    ["c", "Ces\xE1reas (C)"]
  ];
  let html = '<div class="hc-genero-gpac">';
  cells.forEach(function(pair) {
    const key = pair[0];
    html += '<div class="field-group hc-genero-gpac-cell"><label>' + esc(pair[1]) + '</label><input type="number" min="0" max="99" step="1" data-genero-part="' + esc(key) + '" data-genero-id="' + esc(spec.id) + '" value="' + esc(val[key] || "") + '" placeholder="0"></div>';
  });
  html += '</div><div class="field-group hc-genero-gpac-notes"><label>Notas adicionales</label><input type="text" data-genero-part="detalle" data-genero-id="' + esc(spec.id) + '" value="' + esc(val.detalle || "") + '" placeholder="Opcional"></div>';
  return html;
}
function detailBodyHtml(spec, val) {
  val = val && typeof val === "object" ? val : {};
  return '<textarea rows="2" data-genero-part="detalle" data-genero-id="' + esc(spec.id) + '" placeholder="Describir si aplica\u2026">' + esc(val.detalle || "") + "</textarea>";
}
function bodyHtmlForSpec(spec, val) {
  switch (spec.kind) {
    case "age":
      return ageBodyHtml(spec, val);
    case "fum":
      return fumBodyHtml(spec, val);
    case "gpac":
      return gpacBodyHtml(spec, val);
    case "medications":
      return '<div class="hc-genero-meds-host" data-genero-meds-id="' + esc(spec.id) + '"></div>';
    case "detail":
    default:
      return detailBodyHtml(spec, val);
  }
}
function readFieldFromDom(spec, row) {
  if (!row || spec.kind === "medications") return {};
  const id = spec.id;
  const out = {};
  row.querySelectorAll('[data-genero-part][data-genero-id="' + id + '"]').forEach(function(el) {
    const part = el.getAttribute("data-genero-part");
    if (part) out[part] = el.value;
  });
  return out;
}
function mountHistoriaGeneroPanel(container, genero, sexo, onChange) {
  if (!container) return;
  const specs = generoFieldSpecsForSex(sexo);
  genero = normalizeGeneroBlock(genero, sexo);
  const medsState = {};
  specs.forEach(function(spec) {
    if (spec.kind === "medications") {
      const val = genero[spec.id] || {};
      medsState[spec.id] = normalizeMedicamentosList(val.medicamentos);
    }
  });
  let html = '<div class="hc-genero-panel">';
  specs.forEach(function(spec) {
    const val = genero[spec.id] || {};
    const full = spec.fullWidth ? " hc-genero-field--full" : "";
    html += '<div class="field-group hc-genero-field' + full + '" data-genero-field="' + esc(spec.id) + '"><label>' + esc(spec.label) + "</label>" + bodyHtmlForSpec(spec, val) + "</div>";
  });
  html += "</div>";
  container.innerHTML = html;
  function emit() {
    const next = {};
    specs.forEach(function(spec) {
      if (spec.kind === "medications") {
        next[spec.id] = { medicamentos: medsState[spec.id] || [] };
        return;
      }
      const row = container.querySelector('[data-genero-field="' + spec.id + '"]');
      next[spec.id] = readFieldFromDom(spec, row);
    });
    onChange(normalizeGeneroBlock(next, sexo));
  }
  specs.forEach(function(spec) {
    if (spec.kind !== "medications") return;
    const host = container.querySelector('[data-genero-meds-id="' + spec.id + '"]');
    if (!host) return;
    mountMedicamentoRows(host, {
      list: medsState[spec.id],
      addLabel: "+ Agregar anticonceptivo / TH",
      emptyHint: "Medicamento, v\xEDa, dosis y frecuencia (anticonceptivos o terapia hormonal).",
      onChange: function(list) {
        medsState[spec.id] = list;
        emit();
      }
    });
  });
  container.querySelectorAll("[data-genero-part]").forEach(function(el) {
    el.addEventListener("input", emit);
  });
}

// public/js/features/historia-clinica-uppercase.mjs
function wireClinicalHistoryUppercase(root) {
  if (!root) return;
  root.querySelectorAll("input, textarea").forEach(function(el) {
    if (!shouldUppercaseHcInput(el)) return;
    el.style.textTransform = "uppercase";
    if (el.dataset.hcUpperWired === "1") return;
    el.dataset.hcUpperWired = "1";
    el.addEventListener("input", function() {
      applyUppercaseToHcInput(el);
    });
  });
}

// public/js/features/historia-clinica-panel/mount-widgets.mjs
